INSERT INTO package_questions (package_id, question_json, hash_logico, order_index, status) VALUES ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A ''escoliose'' é uma curvatura lateral patológica da coluna. Qual o método clínico simples para triagem desse desvio, solicitando que o paciente se incline para a frente?","options":{"a":"Teste de Romberg.","b":"Teste de Adams.","c":"Sinal de Lasegue.","d":"Manobra de Valsalva.","e":"Teste de Trendelenburg."},"answer":"b","rationale":"O teste de Adams permite visualizar a gibosidade costal, evidenciando o componente rotacional da escoliose.","option_rationales":{"a":"Errada. Avalia equilíbrio.","b":"Correta. Exame físico ortopédico básico.","c":"Errada. Avalia compressão radicular (ciatalgia).","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Anatomia","Dorso","Semiologia/Ortopedia"]}', '822249714fc0b105df21ecf6a45db2fb', 325, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O ''latíssimo do dorso'' (grande dorsal) é um músculo amplo que atua sobre o úmero. Qual a sua principal ação?","options":{"a":"Flexão e rotação lateral do braço.","b":"Extensão, adução e rotação medial do braço.","c":"Abdução do braço acima de 90°.","d":"Elevação da escápula.","e":"Protração da escápula."},"answer":"b","rationale":"O latíssimo do dorso é o principal músculo ''trepador'', realizando a adução e extensão potente do braço.","option_rationales":{"a":"Errada.","b":"Correta. Cinesiologia funcional do dorso.","c":"Errada. Função do serrátil anterior e trapézio.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Anatomia","Dorso","Miologia"]}', '921dc39c662166b0a15f4b87ef56d479', 326, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A medula espinal é suprida por artérias longitudinais. Quantas são as artérias ESPINAIS POSTERIORES e de onde elas costumam se originar?","options":{"a":"Uma artéria; originada da aorta.","b":"Duas artérias; originadas das artérias vertebrais ou cerebelares inferiores posteriores (PICA).","c":"Três artérias; originadas das carótidas.","d":"Nenhuma, a medula é suprida apenas por veias.","e":"Duas artérias; originadas das intercostais."},"answer":"b","rationale":"A medula possui uma arterial espinal anterior (no sulco mediano) e duas posteriores (nos sulcos posterolaterais).","option_rationales":{"a":"Errada.","b":"Correta. Vascularização do sistema nervoso central medular.","c":"Errada.","d":"Errada.","e":"Errada. As intercostais dão origem às artérias radiculares."},"difficulty":"Difícil","tags":["Anatomia","Dorso","Angiologia/Neuroanatomia"]}', 'da482db5195d0d7d528e85f34f58b19d', 327, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A ''artéria radicular magna'' (de Adamkiewicz) é o maior suprimento arterial para os segmentos inferiores da medula. Em qual região ela geralmente penetra no canal vertebral?","options":{"a":"Cervical alta.","b":"Torácica inferior ou lombar superior (T9-L2), geralmente à esquerda.","c":"Sacral.","d":"Cervicotorácica (C7-T1).","e":"Lombar baixa (L4-L5)."},"answer":"b","rationale":"A lesão dessa artéria durante cirurgias de aorta abdominal pode causar isquemia medular e paraplegia.","option_rationales":{"a":"Errada.","b":"Correta. Anatomia vascular crítica para cirurgia vascular e neurocirurgia.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Difícil","tags":["Anatomia","Dorso","Angiologia/Cirurgia"]}', '48bf344a7021c5c2be279fc1c05a9f75', 328, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"Os ''músculos multífidos'' são importantes estabilizadores da coluna. A qual grupo de músculos extrínsecos ou intrínsecos eles pertencem?","options":{"a":"Extrínsecos superficiais.","b":"Extrínsecos intermediários.","c":"Intrínsecos profundos (transverso-espinais).","d":"Intrínsecos superficiais.","e":"Músculos do membro superior."},"answer":"c","rationale":"O grupo transverso-espinal inclui os rotadores, multífidos e semiespinais, situando-se profundamente ao eretor da espinha.","option_rationales":{"a":"Errada.","b":"Errada.","c":"Correta. Classificação da musculatura profunda do dorso.","d":"Errada.","e":"Errada."},"difficulty":"Média","tags":["Anatomia","Dorso","Miologia"]}', '6b3ec2fea4d78fea06222020ad291b9f', 329, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A ''vértebra proeminente'' é um ponto de referência palpável na base do pescoço. A qual nível vertebral ela corresponde habitualmente?","options":{"a":"C2.","b":"C6.","c":"C7.","d":"T1.","e":"T4."},"answer":"c","rationale":"C7 possui um processo espinhoso longo e não bífido, sendo o primeiro marco ósseo facilmente identificável na linha média posterior.","option_rationales":{"a":"Errada.","b":"Errada. Tubérculo carótico (de Chassaignac) em C6 é palpável lateralmente.","c":"Correta. Anatomia de superfície.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Anatomia","Dorso/Pescoço","Osteologia/Superfície"]}', '810f936e64b64788e6a591ff54e17aee', 330, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O ''plexo venoso vertebral de Batson'' localiza-se no espaço epidural. Por que esse plexo é clinicamente importante na disseminação de metástases de câncer de próstata ou mama?","options":{"a":"Porque possui válvulas muito fortes.","b":"Porque é um sistema sem válvulas que se comunica com as veias cavas e o sistema ázigo.","c":"Porque drena diretamente para o cérebro.","d":"Porque transporta apenas linfa.","e":"Não tem importância clínica."},"answer":"b","rationale":"A ausência de válvulas permite que alterações de pressão (como a manobra de Valsalva) revertam o fluxo, levando células tumorais para as vértebras.","option_rationales":{"a":"Errada. É justamente a falta de válvulas.","b":"Correta. Patologia anatômica da disseminação tumoral.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Difícil","tags":["Anatomia","Dorso","Angiologia/Oncologia"]}', '82aca1600251cf607025ddaab99ca555', 331, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"As articulações entre os processos articulares superiores e inferiores de vértebras adjacentes são conhecidas como:","options":{"a":"Sinfises intervertebrais.","b":"Articulações zigapofisárias (facetárias).","c":"Sindesmoses.","d":"Gomfoses.","e":"Esquindileses."},"answer":"b","rationale":"São articulações sinoviais do tipo plana que orientam o tipo de movimento permitido em cada região da coluna.","option_rationales":{"a":"Errada. Refere-se à união pelos discos.","b":"Correta. Artrologia da coluna vertebral.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Média","tags":["Anatomia","Dorso","Artrologia"]}', 'ca26b876f1079f313fccb03e73066275', 332, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"Qual movimento vertebral é mais AMPLO na região CERVICAL em comparação com a região LOMBAR?","options":{"a":"Extensão.","b":"Flexão lateral.","c":"Rotação.","d":"Circundução.","e":"Todos os movimentos são maiores na lombar."},"answer":"c","rationale":"A disposição das facetas articulares cervicais favorece a rotação, enquanto as lombares a bloqueiam quase completamente.","option_rationales":{"a":"Errada.","b":"Errada.","c":"Correta. Biomecânica regional comparada.","d":"Errada.","e":"Errada."},"difficulty":"Média","tags":["Anatomia","Dorso","Biomecânica"]}', '4106cc0c495a4d8e2d72a8c86e6d5ccb', 333, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O ''nervo occipital maior'' origina-se de qual ramo nervoso?","options":{"a":"Ramo anterior de C1.","b":"Ramo posterior de C2.","c":"Ramo anterior de C2.","d":"Ramo posterior de C3.","e":"Plexo cervical superficial."},"answer":"b","rationale":"Ao contrário da maioria dos ramos posteriores que são apenas motores, o de C2 é volumoso e fornece sensibilidade ao couro cabeludo posterior.","option_rationales":{"a":"Errada. Nervo suboccipital (puramente motor).","b":"Correta. Neuroanatomia sensitiva da cabeça/pescoço.","c":"Errada.","d":"Errada. Terceiro nervo occipital.","e":"Errada."},"difficulty":"Difícil","tags":["Anatomia","Dorso/Cabeça","Neuroanatomia"]}', '6efa4646d01401d7d7cf1fa7001d5597', 334, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A ''estenose do canal vertebral'' é o estreitamento do espaço por onde passa a medula ou cauda equina. Qual estrutura hipertrofiada é causa comum de compressão posterior?","options":{"a":"Ligamento longitudinal anterior.","b":"Ligamento amarelo.","c":"Disco intervertebral (anterior).","d":"Processo espinhoso.","e":"Gordura epidural."},"answer":"b","rationale":"A hipertrofia e calcificação do ligamento amarelo reduzem o espaço posterior do canal, comprimindo elementos neurais.","option_rationales":{"a":"Errada.","b":"Correta. Anatomia aplicada ao envelhecimento da coluna.","c":"Errada. Seria compressão anterior.","d":"Errada.","e":"Errada."},"difficulty":"Média","tags":["Anatomia","Dorso","Patologia/Artrologia"]}', '072cd9869fb4877e48dde0f152d591dd', 335, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"Quantas vértebras compõem o SACRO no adulto?","options":{"a":"3 vértebras.","b":"5 vértebras fundidas.","c":"7 vértebras.","d":"1 vértebra única desde o nascimento.","e":"Varia entre 2 e 8."},"answer":"b","rationale":"O sacro resulta da fusão de cinco vértebras sacrais, formando uma base sólida para a pelve.","option_rationales":{"a":"Errada.","b":"Correta. Osteologia do esqueleto axial.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Anatomia","Dorso/Pelve","Osteologia"]}', '78e3683413e840d30e532a72ef1b354d', 336, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O ''promontório sacral'' é um marco importante em obstetrícia. Ele corresponde a qual parte do sacro?","options":{"a":"Ápice do sacro.","b":"Borda anterior da base (S1).","c":"Crista sacral mediana.","d":"Asas do sacro.","e":"Hiato sacral."},"answer":"b","rationale":"A projeção anterior de S1 delimita o estreito superior da pelve.","option_rationales":{"a":"Errada.","b":"Correta. Osteologia pélvica aplicada.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Anatomia","Dorso/Pelve","Osteologia"]}', '6ba213b4c55d33c4ce3f3b85ab8e2510', 337, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A ''dura-máter'' espinal termina em um saco dural cego. Em qual nível vertebral ocorre habitualmente esse término no ADULTO?","options":{"a":"L2.","b":"S2.","c":"S5.","d":"L5.","e":"Coccix."},"answer":"b","rationale":"O espaço subaracnoideo termina em S2, nível onde a dura-máter se funde ao filum terminale.","option_rationales":{"a":"Errada. É o término da medula.","b":"Correta. Anatomia das meninges espinais.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Média","tags":["Anatomia","Dorso","Neuroanatomia"]}', '346cf6f4ddcfe6afde7019ae235cfa61', 338, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"Qual ligamento conecta os ÁPICES dos processos espinhosos de C7 até o sacro?","options":{"a":"Ligamento interespinhal.","b":"Ligamento supraespinhal.","c":"Ligamento nucal.","d":"Ligamento amarelo.","e":"Membrana tectorial."},"answer":"b","rationale":"O ligamento supraespinhal corre sobre as pontas das espinhas vertebrais.","option_rationales":{"a":"Errada. Fica entre as espinhas.","b":"Correta. Artrologia da coluna vertebral.","c":"Errada. É a continuação cervical.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Anatomia","Dorso","Artrologia"]}', 'e846313744fa7f620512e113a2b1597e', 339, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O ''músculo romboide maior'' situa-se profundamente ao trapézio. Qual a sua função em relação à escápula?","options":{"a":"Protração (abdução).","b":"Retração (adução) e rotação inferior.","c":"Elevação pura.","d":"Depressão.","e":"Rotação superior."},"answer":"b","rationale":"Os romboides puxam a escápula em direção à coluna e ajudam a estabilizar a cintura escapular.","option_rationales":{"a":"Errada. Função do serrátil anterior.","b":"Correta. Miologia da cintura escapular.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Média","tags":["Anatomia","Dorso","Miologia"]}', '96715fed2f2a13630fbfe30583b1a1a4', 340, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A ''discite'' é a inflamação do disco intervertebral. Como se caracteriza a vascularização do disco no ADULTO?","options":{"a":"Altamente vascularizado por artérias diretas.","b":"Avascular, nutrindo-se por difusão a partir das placas terminais vertebrais.","c":"Vascularizado apenas na periferia por veias.","d":"Vascularizado apenas na infância, tornando-se ósseo no adulto.","e":"Dependente da medula espinal."},"answer":"b","rationale":"A natureza avascular do disco dificulta a cura de infecções e acelera processos degenerativos.","option_rationales":{"a":"Errada.","b":"Correta. Fisiologia e nutrição tecidual da coluna.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Média","tags":["Anatomia","Dorso","Fisiologia/Patologia"]}', 'd98fda9de90302384eb23cad85635d59', 341, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"No ''sacro'', os nervos espinais sacrais saem por quais aberturas?","options":{"a":"Forames intervertebrais únicos laterais.","b":"Forames sacrais anteriores (ventrais) e posteriores (dorsais).","c":"Apenas pelo hiato sacral.","d":"Pelos forames transversários.","e":"Pelo canal auditivo."},"answer":"b","rationale":"O sacro possui quatro pares de forames de cada lado para permitir a saída dos ramos ventrais e dorsais dos nervos S1-S4.","option_rationales":{"a":"Errada.","b":"Correta. Osteologia sacral e saída nervosa.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Anatomia","Dorso","Osteologia"]}', '80bc347f49f413d1b3a64e2c40c959cf', 342, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O ''sulco da artéria vertebral'' localiza-se em qual parte do Atlas (C1)?","options":{"a":"Processo espinhoso.","b":"Face superior do arco posterior.","c":"Face inferior do arco anterior.","d":"Massa lateral interna.","e":"Forame transverso."},"answer":"b","rationale":"Após passar pelo forame transverso de C1, a artéria vertebral repousa sobre o arco posterior antes de entrar no forame magno.","option_rationales":{"a":"Errada.","b":"Correta. Osteologia cervical específica.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Difícil","tags":["Anatomia","Dorso/Pescoço","Osteologia/Angiologia"]}', '02a2a5710360999b3d4f24afb77f27f7', 343, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"Quais são os limites do ''espaço epidural'' na coluna vertebral?","options":{"a":"Entre a pia-máter e a medula.","b":"Entre a dura-máter e o periósteo do canal vertebral.","c":"Entre a aracnoide e a dura-máter.","d":"Lado externo da pele.","e":"Dentro dos ventrículos."},"answer":"b","rationale":"O espaço epidural contém gordura, plexos venosos e raízes nervosas, sendo o local de injeção de anestésicos epidurais.","option_rationales":{"a":"Errada.","b":"Correta. Espaços meníngeos e relevância clínica.","c":"Errada. Seria o espaço subdural.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Anatomia","Dorso","Neuroanatomia"]}', 'f22165ce069315ef72a1b7217a3e86bf', 344, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A ''síndrome da cauda equina'' é uma emergência médica. Quais são os sintomas clássicos decorrentes da compressão das raízes nervosas terminais?","options":{"a":"Paralisia facial e perda de visão.","b":"Dor lombar, anestesia em sela e disfunção esfincteriana (bexiga/reto).","c":"Cefaleia e vômitos em jato.","d":"Fraqueza apenas nos braços.","e":"Taquicardia e hipertensão."},"answer":"b","rationale":"A compressão em níveis lombossacrais afeta nervos que suprem o períneo e o controle visceral.","option_rationales":{"a":"Errada.","b":"Correta. Anatomia aplicada à neurologia de emergência.","c":"Errada. Sinais de hipertensão intracraniana.","d":"Errada.","e":"Errada."},"difficulty":"Média","tags":["Anatomia","Dorso","Clínica/Neuroanatomia"]}', '6ab8c36b321e395c5828e330fe14f109', 345, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O ''músculo serrátil posterior inferior'' tem qual função respiratória?","options":{"a":"Eleva as costelas (inspiração).","b":"Deprime as costelas (expiração).","c":"Nenhuma função respiratória.","d":"Gira a escápula.","e":"Flexiona a coluna."},"answer":"b","rationale":"O serrátil posterior inferior atua deprimindo as costelas inferiores.","option_rationales":{"a":"Errada. Função do serrátil posterior superior.","b":"Correta. Miologia respiratória acessória.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Média","tags":["Anatomia","Dorso/Tórax","Miologia"]}', '6f4413c3ac08f8669fd7e93cdc62f572', 346, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"Quantas vértebras COCCÍGEAS costumam existir e qual a sua condição no adulto?","options":{"a":"7 vértebras móveis.","b":"4 vértebras rudimentares geralmente fundidas.","c":"1 vértebra única sem divisões.","d":"Depende da altura do indivíduo.","e":"Não existem vértebras no cóccix."},"answer":"b","rationale":"O cóccix é o vestígio da cauda em mamíferos, composto por 4 pequenas vértebras fundidas.","option_rationales":{"a":"Errada.","b":"Correta. Osteologia axial.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Anatomia","Dorso","Osteologia"]}', 'e10cbd08da144358ef58b9fdd59f19ae', 347, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"A ''lordose'' é a curvatura com convexidade anterior. Em quais regiões da coluna ela é considerada fisiológica no adulto?","options":{"a":"Torácica e Sacral.","b":"Cervical e Lombar.","c":"Apenas na Lombar.","d":"Toda a coluna deve ser reta.","e":"Torácica e Lombar."},"answer":"b","rationale":"Cervical e lombar possuem lordose compensatória necessária para a bipedestação.","option_rationales":{"a":"Errada. Possuem cifose.","b":"Correta. Morfologia normal da coluna vertebral.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Fácil","tags":["Anatomia","Dorso","Osteologia"]}', '74a09e21a010645f53dfd85efa3c0113', 348, 'draft'), ('4a6f7797-c62a-4002-b6b5-d7eb76f1d903', '{"enunciado":"O ''ligamento alar'' conecta o dente do Áxis a qual osso?","options":{"a":"Atlas (massas laterais).","b":"Condilos occipitais.","c":"Mandíbula.","d":"Osso hioide.","e":"Processo mastoide."},"answer":"b","rationale":"Os ligamentos alares estendem-se do dente aos côndilos occipitais, limitando a rotação excessiva do crânio.","option_rationales":{"a":"Errada.","b":"Correta. Estabilidade da articulação atlanto-occipital.","c":"Errada.","d":"Errada.","e":"Errada."},"difficulty":"Difícil","tags":["Anatomia","Dorso/Cabeça","Artrologia"]}', '905280aeb7498745debdca440385b40f', 349, 'draft');